#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Purpose: provision everything CI needs for per-PR preview deployments
# (issue #23) and for the production deploy on `master` to actually work —
# Neon + Cloudflare repo secrets, the Pages project, a real Resend key, the
# production Worker secrets, and the Pages production API_URL binding.
#
# Run it from anywhere:  ./scripts/setup-deploy.sh
# Safe to re-run: it remembers values already saved in ./.env (gitignored).
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=7

# Always operate on the repo, no matter where the script was launched from.
cd "$(git rev-parse --show-toplevel)"

banner "VMB: per-PR previews + production deploy setup"

# The production apex. The vmb-web Pages project serves it and the vmb-api
# Worker serves the `api` subdomain (ADR-0022); override to target another
# zone. Set from the environment or prompted for in stage 3.
PROD_DOMAIN="${PROD_DOMAIN:-vmblogistics.id}"

# put_worker_secret NAME VALUE attaches a runtime secret to the vmb-api Worker.
# Value via stdin so it never lands in argv, shell history, or `ps`.
#
# `--env=""` selects the top-level (production) environment explicitly. It is
# the mechanism wrangler's own multi-environment warning documents: without it,
# the [env.staging] block in wrangler.toml makes every deploy-class command warn
# that no target was chosen.
put_worker_secret() {
  local name="$1" value="$2" err
  if [[ -z "$value" ]]; then warn "skipping Worker secret $name (empty)"; return 0; fi
  if err=$(printf '%s' "$value" | pnpm --filter @vmb/api exec wrangler secret put "$name" --name vmb-api --env="" 2>&1 >/dev/null); then
    say "set Worker secret: $name"
  else
    warn "failed to set Worker secret: $name"
    note "$err"
    SKIPPED+=("wrangler secret put $name")
  fi
}

# sync_fnox NAME VALUE updates the committed fnox store so the preview workflow
# (ADR-0019) picks the value up. Value via stdin, never argv or history.
sync_fnox() {
  local name="$1" value="$2"
  if [[ -z "$value" ]]; then return 0; fi
  if printf '%s' "$value" | fnox set "$name" 2>/dev/null; then
    say "updated fnox: $name"
  else
    warn "couldn't update fnox $name (age key missing?) — previews keep the old value."
    SKIPPED+=("fnox set $name")
  fi
  write_env "$name" "$value"
}

# ── Stage 1: Neon API key ─────────────────────────────────────────────────
stage "Neon: API key (repo secret)"
say "CI creates an isolated Neon branch per PR (issue #23), which needs an API key."
open_url "https://console.neon.tech/app/settings/api-keys"
step "Click 'Create API key' and name it something like 'vmb-ci'."
step "Copy the key — it is only shown once."
ask_secret NEON_API_KEY "Paste the Neon API key:"
if [[ -n "$NEON_API_KEY" ]]; then
  set_secret NEON_API_KEY "$NEON_API_KEY"
else
  warn "no key entered — previews will not run until this is set."
fi

# ── Stage 2: Neon project ID ──────────────────────────────────────────────
stage "Neon: project ID (repo secret)"
say "The create-branch action also needs the project ID."
open_url "https://console.neon.tech/app/projects"
step "Open the project this app uses (the one whose connection string is in fnox)."
step "Go to Settings → General and copy 'Project ID'."
ask NEON_PROJECT_ID "Paste the Neon project ID:"
if [[ -n "$NEON_PROJECT_ID" ]]; then
  set_secret NEON_PROJECT_ID "$NEON_PROJECT_ID"
else
  warn "no project ID entered — previews will not run until this is set."
fi

# ── Stage 3: Cloudflare credentials + workers.dev subdomain ───────────────
stage "Cloudflare: API token + account ID"
say "CI deploys the API Worker and the web Pages project with these."
open_url "https://dash.cloudflare.com/profile/api-tokens"
step "Create an API token with these account permissions:"
note "  • Account → Workers Scripts → Edit   (upload API preview versions)"
note "  • Account → Cloudflare Pages → Edit  (deploy the web preview + production)"
note "  • Account → Account Settings → Read  (read the workers.dev subdomain)"
note "  • Zone → Zone → Read                 (look up the production zone)"
note "  • Zone → Workers Routes → Edit       (bind the API custom domain on deploy)"
step "Copy the token."
ask_secret CLOUDFLARE_API_TOKEN "Paste the Cloudflare API token:"
step "Copy the Account ID from the Workers & Pages overview (right sidebar, or the dashboard URL)."
open_url "https://dash.cloudflare.com/?to=/:account/workers-and-pages"
ask CLOUDFLARE_ACCOUNT_ID "Paste the Cloudflare account ID:"
PROD_DOMAIN_DEFAULT="$PROD_DOMAIN"
step "Confirm the production domain whose zone serves the app (default: $PROD_DOMAIN_DEFAULT)."
ask PROD_DOMAIN "Production domain (apex):"
PROD_DOMAIN="${PROD_DOMAIN:-$PROD_DOMAIN_DEFAULT}"

if [[ -n "$CLOUDFLARE_API_TOKEN" && -n "$CLOUDFLARE_ACCOUNT_ID" ]]; then
  set_secret CLOUDFLARE_API_TOKEN "$CLOUDFLARE_API_TOKEN"
  set_secret CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"
  export CLOUDFLARE_API_TOKEN CLOUDFLARE_ACCOUNT_ID
  write_env CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"
  write_env CLOUDFLARE_API_TOKEN "$CLOUDFLARE_API_TOKEN"

  # Resolve the account's workers.dev subdomain so a fallback production URL
  # exists. Response shape: {"result":{"subdomain":"..."}}.
  response=$(curl -fsS -H "Authorization: Bearer $CLOUDFLARE_API_TOKEN" \
    "https://api.cloudflare.com/client/v4/accounts/$CLOUDFLARE_ACCOUNT_ID/workers/subdomain" || true)
  CLOUDFLARE_WORKERS_SUBDOMAIN=$(printf '%s' "$response" | sed -n 's/.*"subdomain"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p')

  # Prefer the custom domain (issue #31, ADR-0022). It is only usable once the
  # zone is active in this account, so look the zone up by name and fall back to
  # workers.dev / pages.dev otherwise. Resolving the zone needs Zone:Read; the
  # call returns an empty result set (not an error) when the domain is not in
  # this account.
  zone_response=$(curl -fsS -H "Authorization: Bearer $CLOUDFLARE_API_TOKEN" \
    "https://api.cloudflare.com/client/v4/zones?name=$PROD_DOMAIN" || true)
  ZONE_ID=$(printf '%s' "$zone_response" | jq -r '.result[0].id // empty' 2>/dev/null || true)
  ZONE_STATUS=$(printf '%s' "$zone_response" | jq -r '.result[0].status // empty' 2>/dev/null || true)

  if [[ -n "$ZONE_ID" && "$ZONE_STATUS" == "active" ]]; then
    API_PROD_URL="https://api.${PROD_DOMAIN}"
    WEB_PROD_URL="https://${PROD_DOMAIN}"
    write_env PROD_DOMAIN "$PROD_DOMAIN"
    write_env ZONE_ID "$ZONE_ID"
    say "zone '$PROD_DOMAIN' is active — production URLs use the custom domain."
  elif [[ -n "$CLOUDFLARE_WORKERS_SUBDOMAIN" ]]; then
    API_PROD_URL="https://vmb-api.${CLOUDFLARE_WORKERS_SUBDOMAIN}.workers.dev"
    WEB_PROD_URL="https://vmb-web.pages.dev"
    warn "zone '$PROD_DOMAIN' is not active in this account — falling back to workers.dev / pages.dev."
    warn "add the domain as a zone, then re-run to switch production to the custom domain."
  else
    warn "neither an active zone '$PROD_DOMAIN' nor a workers.dev subdomain was found."
    warn "check the token's Workers and Zone scopes, then re-run."
    SKIPPED+=("Resolve production URLs (Cloudflare credentials/scopes)")
  fi

  [[ -n "$CLOUDFLARE_WORKERS_SUBDOMAIN" ]] && write_env CLOUDFLARE_WORKERS_SUBDOMAIN "$CLOUDFLARE_WORKERS_SUBDOMAIN"
  [[ -n "${API_PROD_URL:-}" ]] && write_env API_PROD_URL "$API_PROD_URL"
  [[ -n "${WEB_PROD_URL:-}" ]] && write_env WEB_PROD_URL "$WEB_PROD_URL"
  [[ -n "$CLOUDFLARE_WORKERS_SUBDOMAIN" ]] && say "workers.dev subdomain: $CLOUDFLARE_WORKERS_SUBDOMAIN"
  [[ -n "${API_PROD_URL:-}" ]] && say "API will live at: $API_PROD_URL"
  [[ -n "${WEB_PROD_URL:-}" ]] && say "Web will live at: $WEB_PROD_URL"
else
  warn "missing Cloudflare credentials — later deploy stages will be skipped."
fi

# CI decrypts fnox (ADR-0011) with this repo secret; without it, build-and-test
# and the preview workflow both fail before doing anything useful.
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  if ! gh secret list 2>/dev/null | grep -q '^FNOX_AGE_KEY'; then
    warn "repo secret FNOX_AGE_KEY is missing — CI cannot decrypt the fnox store."
    SKIPPED+=("Set repo secret FNOX_AGE_KEY")
  else
    say "repo secret FNOX_AGE_KEY present."
  fi
fi

# ── Stage 4: Pages project ────────────────────────────────────────────────
stage "Cloudflare Pages: project 'vmb-web'"
if [[ -n "${CLOUDFLARE_API_TOKEN:-}" ]]; then
  say "Checking for an existing Pages project named 'vmb-web'..."
  if pnpm --filter @vmb/web exec wrangler pages project list 2>/dev/null | grep -q 'vmb-web'; then
    say "Found it — nothing to create."
  else
    warn "No 'vmb-web' project found; CI's Pages deploy would fail without it."
    if confirm "Create it now on production branch 'master'?"; then
      pnpm --filter @vmb/web exec wrangler pages project create vmb-web --production-branch master \
        || warn "create failed — create it in the dashboard instead."
    else
      SKIPPED+=("Create the vmb-web Pages project (production branch master)")
    fi
  fi
else
  warn "skipped: no Cloudflare credentials from stage 3."
  SKIPPED+=("Create the vmb-web Pages project (production branch master)")
fi

# Attach the apex to the Pages project so the zone serves the app at the custom
# domain (ADR-0022). Pages custom domains are configured through the Pages API,
# not wrangler.toml, and the apex must not also carry a Worker route — which is
# why the API Worker takes the `api` subdomain instead.
if [[ -n "${CLOUDFLARE_API_TOKEN:-}" && -n "${ZONE_ID:-}" && "${ZONE_STATUS:-}" == "active" ]]; then
  say "Attaching $PROD_DOMAIN to the vmb-web Pages project..."
  domains_response=$(curl -fsS -H "Authorization: Bearer $CLOUDFLARE_API_TOKEN" \
    "https://api.cloudflare.com/client/v4/accounts/$CLOUDFLARE_ACCOUNT_ID/pages/projects/vmb-web/domains" 2>/dev/null || true)
  if printf '%s' "$domains_response" | jq -r '.result[]?.name' 2>/dev/null | grep -Fxq "$PROD_DOMAIN"; then
    say "$PROD_DOMAIN is already attached."
  else
    attach_response=$(curl -sS -X POST \
      -H "Authorization: Bearer $CLOUDFLARE_API_TOKEN" \
      -H "Content-Type: application/json" \
      "https://api.cloudflare.com/client/v4/accounts/$CLOUDFLARE_ACCOUNT_ID/pages/projects/vmb-web/domains" \
      --data "$(jq -n --arg name "$PROD_DOMAIN" '{name:$name}')" 2>&1)
    if printf '%s' "$attach_response" | jq -e '.success == true' >/dev/null 2>&1; then
      say "attached $PROD_DOMAIN to vmb-web"
    else
      warn "couldn't attach $PROD_DOMAIN — add it in the dashboard (Pages → vmb-web → Custom domains)."
      note "$(printf '%s' "$attach_response" | jq -r '.errors[0].message // empty' 2>/dev/null || true)"
      SKIPPED+=("Attach $PROD_DOMAIN to the vmb-web Pages project")
    fi
  fi
  say "www: add a Single Redirect rule for https://www.$PROD_DOMAIN/* → https://$PROD_DOMAIN/\$1 (301) in the zone."
fi
open_url "https://dash.cloudflare.com/?to=/:account/workers-and-pages"

# ── Stage 5: Resend ───────────────────────────────────────────────────────
stage "Resend: API key + sender"
say "Signup verification emails need a real key to actually send."
open_url "https://resend.com/api-keys"
step "Create an API key with Sending access and copy it."
ask_secret RESEND_API_KEY "Paste the Resend API key:"
step "Use the verified custom-domain sender (default: noreply@$PROD_DOMAIN)."
note "Resend's sandbox 'onboarding@resend.dev' only delivers to the account owner's address, so it cannot be the production sender."
note "Every Resend DNS record must be DNS only (grey cloud) — a proxied record fails verification with error 1004."
# Pre-fill the verified custom-domain sender so Enter accepts it, then persist
# whatever is entered so a re-run offers it as the default.
[[ -n "$(_existing EMAIL_FROM || true)" ]] || write_env EMAIL_FROM "noreply@$PROD_DOMAIN"
ask EMAIL_FROM "Sender address (From):"
[[ "$EMAIL_FROM" == "$(_existing EMAIL_FROM || true)" ]] || write_env EMAIL_FROM "$EMAIL_FROM"

# Previews read RESEND_API_KEY / EMAIL_FROM from the committed fnox store, so
# update it there too — not just the production Worker (ADR-0019).
if [[ -z "$RESEND_API_KEY" ]]; then
  warn "no Resend key entered — verification emails will not send."
fi
sync_fnox RESEND_API_KEY "${RESEND_API_KEY:-}"
sync_fnox EMAIL_FROM "${EMAIL_FROM:-}"
note "fnox.toml changed — commit it so CI picks up the new values."

# ── Stage 6: production Worker secrets ────────────────────────────────────
stage "Production Worker secrets (vmb-api)"
say "Runtime secrets on the deployed API Worker — not GitHub secrets."

open_url "https://console.neon.tech/app/projects"
step "Open the project → Connection string → copy the default-branch (production) URL."
ask_secret DATABASE_URL "Paste the production DATABASE_URL:"

generated_secret=$(openssl rand -base64 32)
say "A fresh BETTER_AUTH_SECRET will be used unless you paste your own."
ask_secret BETTER_AUTH_SECRET "Session secret (Enter to use the generated one):"
BETTER_AUTH_SECRET="${BETTER_AUTH_SECRET:-$generated_secret}"

# Seed ask's defaults with the computed production URLs; custom domains welcome.
[[ -n "${API_PROD_URL:-}" ]] && write_env BETTER_AUTH_URL "$API_PROD_URL"
[[ -n "${WEB_PROD_URL:-}" ]] && write_env WEB_URL "$WEB_PROD_URL"
ask BETTER_AUTH_URL "Public API URL (BETTER_AUTH_URL):"
ask WEB_URL "Public web URL (WEB_URL):"

# BETTER_AUTH_URL/WEB_URL reach the Worker secrets and the Pages API_URL
# binding only — deliberately NOT the fnox store. fnox is the local-dev / CI
# store (ADR-0011) holding the `wrangler dev` origins; previews override both
# per PR (ADR-0019), so the production origins are not written there.

if [[ -n "${CLOUDFLARE_API_TOKEN:-}" ]]; then
  say "Creating/updating the Worker so secrets can be attached to it..."
  pnpm --filter @vmb/api exec wrangler deploy --env="" \
    || warn "wrangler deploy failed — set the secrets once the Worker exists."

  put_worker_secret DATABASE_URL "$DATABASE_URL"
  put_worker_secret BETTER_AUTH_SECRET "$BETTER_AUTH_SECRET"
  put_worker_secret BETTER_AUTH_URL "$BETTER_AUTH_URL"
  put_worker_secret WEB_URL "$WEB_URL"
  put_worker_secret RESEND_API_KEY "${RESEND_API_KEY:-}"
  put_worker_secret EMAIL_FROM "${EMAIL_FROM:-}"
else
  warn "skipped: no Cloudflare credentials from stage 3."
  SKIPPED+=("Set production Worker secrets")
fi

# ── Stage 7: Pages production API_URL binding ─────────────────────────────
stage "Pages: production API_URL binding"
say "In production the web app reads its API URL from a Pages env var."
if [[ -n "${CLOUDFLARE_API_TOKEN:-}" && -n "${BETTER_AUTH_URL:-}" ]]; then
  # Plaintext Pages env var, set through the Pages project API. `wrangler pages
  # secret put` mislabels it an encrypted secret and needs an existing
  # deployment to target, which a freshly created project doesn't have.
  # PATCH: /accounts/{account_id}/pages/projects/{project_name}
  pages_body=$(jq -n --arg url "$BETTER_AUTH_URL" \
    '{deployment_configs:{production:{env_vars:{API_URL:{type:"plain_text",value:$url}}}}}')
  pages_response=$(curl -sS -X PATCH \
    -H "Authorization: Bearer $CLOUDFLARE_API_TOKEN" \
    -H "Content-Type: application/json" \
    "https://api.cloudflare.com/client/v4/accounts/$CLOUDFLARE_ACCOUNT_ID/pages/projects/vmb-web" \
    --data "$pages_body" 2>&1)

  if printf '%s' "$pages_response" | jq -e '.success == true' >/dev/null 2>&1; then
    say "set Pages production env var: API_URL"
  else
    warn "couldn't set API_URL — set it in the dashboard (Settings → Variables and Secrets → Production)."
    note "$(printf '%s' "$pages_response" | jq -r '.errors[0].message // empty' 2>/dev/null || true)"
    SKIPPED+=("Pages production API_URL binding")
  fi
else
  warn "skipped: missing Cloudflare credentials or API URL."
  SKIPPED+=("Pages production API_URL binding")
fi
open_url "https://dash.cloudflare.com/?to=/:account/workers-and-pages"

# ──────────────────────────────────────────────────────────────────────────

finish
